  "dependabot/list-alerts-for-repo": {
    "accessPath": [
      "dependabot",
      "listAlertsForRepo"
    ],
    "bodyAllowsAdditionalProperties": false,
    "bodyKind": "none",
    "bodyPropertyKeys": [],
    "contentType": "application/json",
    "headerParameterKeys": [],
    "method": "GET",
    "routeTemplate": "/repos/{owner}/{repo}/dependabot/alerts",
    "pathConflictKeys": [],
    "pathParameterKeys": [
      "owner",
      "repo"
    ],
    "queryConflictKeys": [],
    "queryParameterKeys": [
      "classification",
      "state",
      "severity",
      "ecosystem",
      "package",
      "manifest",
      "epss_percentage",
      "has",
      "assignee",
      "scope",
      "sort",
      "direction",
      "before",
      "after",
      "per_page"
    ],
    "description": "List Dependabot alerts for a repository",
    "parameterDescriptions": {
      "owner": "The account owner of the repository. The name is not case sensitive.",
      "repo": "The name of the repository without the `.git` extension. The name is not case sensitive.",
      "classification": "A comma-separated list of vulnerability classifications. If specified, only alerts for vulnerabilities with these classifications will be returned.\n\nCan be: `malware`, `general`",
      "state": "A comma-separated list of states. If specified, only alerts with these states will be returned.\n\nCan be: `auto_dismissed`, `dismissed`, `fixed`, `open`",
      "severity": "A comma-separated list of severities. If specified, only alerts with these severities will be returned.\n\nCan be: `low`, `medium`, `high`, `critical`",
      "ecosystem": "A comma-separated list of ecosystems. If specified, only alerts for these ecosystems will be returned.\n\nCan be: `composer`, `go`, `maven`, `npm`, `nuget`, `pip`, `pub`, `rubygems`, `rust`",
      "package": "A comma-separated list of package names. If specified, only alerts for these packages will be returned.",
      "manifest": "A comma-separated list of full manifest paths. If specified, only alerts for these manifests will be returned.",
      "epss_percentage": "CVE Exploit Prediction Scoring System (EPSS) percentage. Can be specified as:\n- An exact number (`n`)\n- Comparators such as `>n`, `<n`, `>=n`, `<=n`\n- A range like `n..n`, where `n` is a number from 0.0 to 1.0\n\nFilters the list of alerts based on EPSS percentages. If specified, only alerts with the provided EPSS percentages will be returned.",
      "has": "Filters the list of alerts based on whether the alert has the given value. If specified, only alerts meeting this criterion will be returned.\nMultiple `has` filters can be passed to filter for alerts that have all of the values. Currently, only `patch` is supported.",
      "assignee": "Filter alerts by assignees.\nProvide a comma-separated list of user handles (e.g., `octocat` or `octocat,hubot`) to return alerts assigned to any of the specified users.\nUse `*` to list alerts with at least one assignee or `none` to list alerts with no assignees.",
      "scope": "The scope of the vulnerable dependency. If specified, only alerts with this scope will be returned.",
      "sort": "The property by which to sort the results.\n`created` means when the alert was created.\n`updated` means when the alert's state last changed.\n`epss_percentage` sorts alerts by the Exploit Prediction Scoring System (EPSS) percentage.",
      "direction": "The direction to sort the results by.",
      "before": "A cursor, as given in the [Link header](https://docs.github.com/rest/guides/using-pagination-in-the-rest-api#using-link-headers). If specified, the query only searches for results before this cursor. For more information, see \"[Using pagination in the REST API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the-rest-api).\"",
      "after": "A cursor, as given in the [Link header](https://docs.github.com/rest/guides/using-pagination-in-the-rest-api#using-link-headers). If specified, the query only searches for results after this cursor. For more information, see \"[Using pagination in the REST API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the-rest-api).\"",
      "per_page": "The number of results per page (max 100). For more information, see \"[Using pagination in the REST API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the-rest-api).\""
    }
  },
